import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";
import { ProviderAuth } from "./contexte/ContexteAuth";
import { ProviderPanier } from "./contexte/ContextePanier";
import BarreNavigation from "./components/layout/BarreNavigation";
import PiedDePage from "./components/layout/PiedDePage";
import { useAuth } from "./hooks/useAuth";
import { usePanier } from "./hooks/usePanier";
import Accueil from "./pages/Accueil";
import Catalogue from "./pages/Catalogue";
import DetailProduit from "./pages/DetailProduit";
import Panier from "./pages/Panier";
import MesCommandes from "./pages/MesCommandes";
import Connexion from "./pages/Connexion";
import Inscription from "./pages/Inscription";
import Profil from "./pages/Profil";

function Topbar() {
  const { utilisateur } = useAuth();
  const { totalArticles } = usePanier();
  const initiale = utilisateur?.nom?.charAt(0).toUpperCase() || "U";

  return (
    <header style={{
      position: "fixed", top: 0, left: "220px", right: 0,
      height: "60px", background: "white",
      borderBottom: "0.5px solid #e9ecef",
      display: "flex", alignItems: "center",
      padding: "0 28px", gap: "16px", zIndex: 99,
    }}>
      {/* Barre recherche */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", gap: "8px", background: "#f8f9fa", border: "0.5px solid #e9ecef", borderRadius: "8px", padding: "8px 14px" }}>
        <span style={{ color: "#adb5bd", fontSize: "14px" }}>🔍</span>
        <input placeholder="Rechercher un produit, une catégorie..." style={{ background: "none", border: "none", outline: "none", fontSize: "14px", color: "#212529", width: "100%", fontFamily: "inherit" }} />
      </div>

      {/* Icônes */}
      <div style={{ position: "relative" }}>
        <div style={{ width: "36px", height: "36px", border: "0.5px solid #e9ecef", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: "16px" }}>🔔</div>
        <span style={{ position: "absolute", top: "-4px", right: "-4px", background: "#E03131", color: "white", fontSize: "10px", fontWeight: 700, width: "16px", height: "16px", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center" }}>2</span>
      </div>

      <div style={{ position: "relative" }}>
        <div style={{ width: "36px", height: "36px", border: "0.5px solid #e9ecef", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: "16px" }}>🛒</div>
        {totalArticles > 0 && (
          <span style={{ position: "absolute", top: "-4px", right: "-4px", background: "#E03131", color: "white", fontSize: "10px", fontWeight: 700, width: "16px", height: "16px", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center" }}>{totalArticles}</span>
        )}
      </div>

      {/* Utilisateur */}
      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
        <div style={{ width: "32px", height: "32px", background: "#3B5BDB", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontSize: "13px", fontWeight: 600 }}>
          {initiale}
        </div>
        <div style={{ fontSize: "13px" }}>
          <div style={{ color: "#adb5bd", fontSize: "11px" }}>Bonjour,</div>
          <div style={{ fontWeight: 600, color: "#212529" }}>{utilisateur?.nom || "Invité"}</div>
        </div>
      </div>
    </header>
  );
}

function Layout() {
  return (
    <div style={{ display: "flex" }}>
      <BarreNavigation />
      <div style={{ marginLeft: "220px", flex: 1, minHeight: "100vh", display: "flex", flexDirection: "column" }}>
        <Topbar />
        <main style={{ marginTop: "60px", flex: 1, padding: "28px" }}>
          <Routes>
            <Route path="/" element={<Accueil />} />
            <Route path="/catalogue" element={<Catalogue />} />
            <Route path="/produit/:id" element={<DetailProduit />} />
            <Route path="/panier" element={<Panier />} />
            <Route path="/mes-commandes" element={<MesCommandes />} />
            <Route path="/connexion" element={<Connexion />} />
            <Route path="/inscription" element={<Inscription />} />
            <Route path="/profil" element={<Profil />} />
          </Routes>
        </main>
        <PiedDePage />
      </div>
    </div>
  );
}
////

export default function App() {
  return (
    <ProviderAuth>
      <ProviderPanier>
        <BrowserRouter>
          <Layout />
        </BrowserRouter>
      </ProviderPanier>
    </ProviderAuth>
  );
}
